const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const jakartaBay = ee.Geometry.Polygon([
    [106.6, -5.9],
    [107.1, -5.9],
    [107.1, -6.2],
    [106.6, -6.2],
    [106.6, -5.9]
  ]);

  const startDate = '2021-01-01';
  const endDate = '2021-12-31';

  // 2. Data Acquisition - Landsat 8 for 2021
  let collection = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(jakartaBay)
    .filterDate(startDate, endDate)
    .filter(ee.Filter.lt('CLOUD_COVER', 20));

  const collectionSize = collection.size().getInfo();
  console.log(`2021 Landsat Images: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log("No Landsat 8 images found, trying Sentinel-2...");
    collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(jakartaBay)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20));

    const sentinelSize = collection.size().getInfo();
    console.log(`2021 Sentinel-2 Images: ${sentinelSize}`);

    if (sentinelSize === 0) {
      console.log("<answer>C1</answer>");
      return;
    }
  }

  // 3. Create median composite and calculate indices
  const composite = collection.median();

  // Calculate NDVI and NDBI for built-up area detection
  const ndvi = composite.normalizedDifference(['SR_B5', 'SR_B4']).rename('NDVI');
  const ndbi = composite.normalizedDifference(['SR_B6', 'SR_B5']).rename('NDBI');

  // Classify artificial land: high NDBI and low NDVI
  const artificialLand = ndbi.gt(0).and(ndvi.lt(0.2));

  // 4. Calculate area
  const areaStats = artificialLand.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: jakartaBay,
    scale: 30,
    maxPixels: 1e9
  });

  const pixelCount = areaStats.get('NDBI').getInfo();

  if (pixelCount === null || pixelCount === undefined) {
    console.log("Calculation failed");
    console.log("<answer>C3</answer>");
    return;
  }

  // Convert pixel count to hectares (30m Landsat pixels)
  const pixelArea = 30 * 30; // square meters per pixel
  const areaHectares = (pixelCount * pixelArea) / 10000;

  console.log(`Artificial land pixels: ${Math.round(pixelCount)}`);
  console.log(`Area (hectares): ${Math.round(areaHectares)}`);

  // 5. Validation & Final Answer
  if (areaHectares > 800) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
